    for (int i = 0; i < n; i++)
        cin >> w[i] >> v[i];
    for (int i = 0; i < n; i++)
        for (int c = W; c >= w[i]; c--)
            if (dp[c - w[i]] + v[i] > dp[c])
                dp[c] = dp[c - w[i]] + v[i];
    cout << dp[W];
}
